#!/bin/sh
# Check load and run of the built emulator over stdin/stdout.
# Program (instruction tuples n/dst/src): (8,0x2000,LAST),
# (8,0x2010,0x2000), (8,LAST,0x2010), 61 NOPs; then stream byte 'Z'.
# Instruction format follows the space size: at default -s 65520 the
# fields are 15+16+16 = 47 bits (n, dst, src; value bit k sits at the
# k-th bit of its field), so the 64-instruction program is 3008 bits =
# 376 bytes. Stream bits continue across accesses; the first bit of a
# stream byte is its high bit. Half-intervals do not overlap.
set -e
cd "$(dirname "$0")/.."
if [ ! -x ./space ]; then
  echo "no ./space, run make first"
  exit 1
fi
printf '' | ./space -t 1 > /tmp/boot_empty.out
test ! -s /tmp/boot_empty.out
echo "ok: empty stdin, silence"
{ printf '\020\000\000\011\357\376\040\000\040\020\000\020\100\007\277\370\100\040\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000'; printf 'Z'; } | timeout 5 ./space -t 3 > /tmp/boot_run.out
printf '\132\132' > /tmp/boot_expected.out
cmp /tmp/boot_run.out /tmp/boot_expected.out
echo "ok: load tick, run tick (ZZ), EOF tick"
{ head -c 100 /dev/zero; } | timeout 5 ./space -t 1 > /tmp/boot_short.out
test ! -s /tmp/boot_short.out
echo "ok: short stream, silence"
{ printf '\020\000\000\011\357\376\040\000\040\020\000\020\100\007\277\370\100\040\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000'; printf 'Z'; } | timeout 5 ./space -t 2 > /tmp/boot_limit.out
printf 'Z' > /tmp/boot_limit_expected.out
cmp /tmp/boot_limit.out /tmp/boot_limit_expected.out
echo "ok: tick limit flag (2 ticks -> Z)"
set +e
./space foo < /dev/null >/dev/null 2>&1
code=$?
set -e
test "$code" -eq 2
echo "ok: bad flag gives exit code 2"
